# --- Circuit Breaker Logic ---
async def check_circuit_breaker():
    global circuit_breaker_failures, circuit_breaker_open_time
    if circuit_breaker_open_time is not None:
        if time.time() - circuit_breaker_open_time > settings.CIRCUIT_BREAKER_RESET_TIMEOUT_SEC:
            logger.warning("Circuit breaker moving to HALF-OPEN state.")
            circuit_breaker_open_time = None # Allow one request to pass
            CIRCUIT_BREAKER_STATE.set(2)
        else:
            raise HTTPException(
                status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
                detail="Circuit breaker is OPEN. Service unavailable."
            )
    
    if circuit_breaker_failures >= settings.CIRCUIT_BREAKER_FAILURE_THRESHOLD:
        logger.error(f"Circuit breaker OPENED due to {circuit_breaker_failures} failures.")
        circuit_breaker_open_time = time.time()
        CIRCUIT_BREAKER_STATE.set(1)
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail="Circuit breaker is OPEN. Service unavailable."
        )

def record_success():
    global circuit_breaker_failures, circuit_breaker_open_time
    if circuit_breaker_open_time is None and CIRCUIT_BREAKER_STATE._value.get(): # If half-open
        logger.info("Circuit breaker moved to CLOSED state after successful request.")
        circuit_breaker_failures = 0
        CIRCUIT_BREAKER_STATE.set(0)
    elif circuit_breaker_open_time is None: # If closed, reset failures
        circuit_breaker_failures = 0

def record_failure():
    global circuit_breaker_failures
    circuit_breaker_failures += 1
    logger.warning(f"Circuit breaker failure count: {circuit_breaker_failures}")

