async def enforce_rate_limit():
    current_time = time.time()
    while not request_timestamps.empty() and request_timestamps.qsize() > settings.MAX_RPS_THRESHOLD:
        oldest_timestamp = await request_timestamps.get()
        if current_time - oldest_timestamp > 1.0: # Remove timestamps older than 1 second
            continue
        else:
            await request_timestamps.put(oldest_timestamp) # Put it back if still within 1 second window
            raise HTTPException(
                status_code=status.HTTP_429_TOO_MANY_REQUESTS,
                detail=f"Rate limit exceeded. Max {settings.MAX_RPS_THRESHOLD} RPS."
            )
    await request_timestamps.put(current_time)

